local known = {}

-- true when the server knows the item (items.otb has it)
function D.installed(name)
	local id = D.ids[name]
	if not id then
		return false
	end
	if known[id] == nil then
		local ok, yes = pcall(function()
			local it = ItemType(id)
			return it ~= nil and it:getId() == id
		end)
		known[id] = (ok and yes) and true or false
	end
	return known[id]
end

-- the server id of a dark tile, or `fallback` when it is not installed (or name is nil)
function D.id(name, fallback)
	if name and D.installed(name) then
		return D.ids[name]
	end
	return fallback
end

-- a list of server ids for a list of names, or `fallback` when any of them is missing
function D.list(names, fallback)
	if type(names) ~= "table" or #names == 0 then
		return fallback
	end
	local out = {}
	for i, name in ipairs(names) do
		if not D.installed(name) then
			return fallback
		end
		out[i] = D.ids[name]
	end
	return out
end
